{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 구청의 동물보호센터 보호시설·보호동물 상태 연 점검 횟수",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청장은 소속 공무원에게 동물보호센터 보호시설의 지정기준 준수 여부와 보호·관리 중인 유기동물의 건강 및 보호·관리 상태를 시행규칙 제21조제3항에 따라 연 두 차례 이상 점검하도록 하여야 한다.",
          "b_ids": "동물보호:제9조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 동물보호 조례상 점검에서 거짓 지정 사실이 확인되면 동물보호센터 지정을 취소해야 하는지",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "점검결과 법 제36조제4항에 해당하는 사항이 발견된 경우 동물보호센터 지정을 취소할 수 있으나, 거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우에는 그 지정을 취소하여야 한다.",
          "b_ids": "동물보호:제9조제2항, 동물보호:제9조제2항단서, 동물보호:제9조제2항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
